agent_motion_timer0(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 0, PT := T#1000ms);
agent_motion_dwell0(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 0 AND agent_motion_timer0.Q AND (ABS(INT_TO_DINT(rb100_j1_actual) - DINT#979) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j2_actual) - DINT#-6619) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j3_actual) - DINT#5180) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j4_actual) - DINT#3892) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j5_actual) - DINT#-3337) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j6_actual) - DINT#4834) <= DINT#1), PT := T#200ms);
agent_motion_timer1(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 1, PT := T#1000ms);
agent_motion_dwell1(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 1 AND agent_motion_timer1.Q AND (ABS(INT_TO_DINT(rb100_j1_actual) - DINT#879) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j2_actual) - DINT#-6719) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j3_actual) - DINT#5180) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j4_actual) - DINT#3892) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j5_actual) - DINT#-3337) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j6_actual) - DINT#4834) <= DINT#1), PT := T#0ms);
agent_motion_timer2(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 2, PT := T#1000ms);
agent_motion_dwell2(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 2 AND agent_motion_timer2.Q AND (ABS(INT_TO_DINT(rb100_j1_actual) - DINT#979) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j2_actual) - DINT#-6619) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j3_actual) - DINT#5180) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j4_actual) - DINT#3892) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j5_actual) - DINT#-3337) <= DINT#1 AND ABS(INT_TO_DINT(rb100_j6_actual) - DINT#4834) <= DINT#1), PT := T#200ms);
agent_motion_timer3(IN := agent_motion_mode = 1 AND rb100_enable = 1 AND agent_motion_state = 3, PT := T#1000ms);
