agent_motion_done := 0;
IF agent_motion_mode = 0 THEN
  agent_motion_state := 0;
ELSIF agent_motion_mode = 1 AND rb100_enable = 1 THEN
  CASE agent_motion_state OF
  0:
    rb100_j1_target := REAL_TO_INT(879.0 + 100.0 * TIME_TO_REAL(agent_motion_timer0.ET) / 1.0);
    rb100_j2_target := REAL_TO_INT(-6719.0 + 100.0 * TIME_TO_REAL(agent_motion_timer0.ET) / 1.0);
    rb100_j3_target := REAL_TO_INT(5180.0 + 0.0 * TIME_TO_REAL(agent_motion_timer0.ET) / 1.0);
    rb100_j4_target := REAL_TO_INT(3892.0 + 0.0 * TIME_TO_REAL(agent_motion_timer0.ET) / 1.0);
    rb100_j5_target := REAL_TO_INT(-3337.0 + 0.0 * TIME_TO_REAL(agent_motion_timer0.ET) / 1.0);
    rb100_j6_target := REAL_TO_INT(4834.0 + 0.0 * TIME_TO_REAL(agent_motion_timer0.ET) / 1.0);
    IF agent_motion_dwell0.Q THEN agent_motion_state := 1; END_IF;
  1:
    rb100_j1_target := REAL_TO_INT(979.0 + -100.0 * TIME_TO_REAL(agent_motion_timer1.ET) / 1.0);
    rb100_j2_target := REAL_TO_INT(-6619.0 + -100.0 * TIME_TO_REAL(agent_motion_timer1.ET) / 1.0);
    rb100_j3_target := REAL_TO_INT(5180.0 + 0.0 * TIME_TO_REAL(agent_motion_timer1.ET) / 1.0);
