    rb100_j2_target := REAL_TO_INT(-6719.0 + 100.0 * TIME_TO_REAL(agent_motion_timer2.ET) / 1.0);
    rb100_j3_target := REAL_TO_INT(5180.0 + 0.0 * TIME_TO_REAL(agent_motion_timer2.ET) / 1.0);
    rb100_j4_target := REAL_TO_INT(3892.0 + 0.0 * TIME_TO_REAL(agent_motion_timer2.ET) / 1.0);
    rb100_j5_target := REAL_TO_INT(-3337.0 + 0.0 * TIME_TO_REAL(agent_motion_timer2.ET) / 1.0);
    rb100_j6_target := REAL_TO_INT(4834.0 + 0.0 * TIME_TO_REAL(agent_motion_timer2.ET) / 1.0);
    IF agent_motion_dwell2.Q THEN agent_motion_state := 3; END_IF;
  3:
    rb100_j1_target := REAL_TO_INT(979.0 + -100.0 * TIME_TO_REAL(agent_motion_timer3.ET) / 1.0);
    rb100_j2_target := REAL_TO_INT(-6619.0 + -100.0 * TIME_TO_REAL(agent_motion_timer3.ET) / 1.0);
    rb100_j3_target := REAL_TO_INT(5180.0 + 0.0 * TIME_TO_REAL(agent_motion_timer3.ET) / 1.0);
    rb100_j4_target := REAL_TO_INT(3892.0 + 0.0 * TIME_TO_REAL(agent_motion_timer3.ET) / 1.0);
    rb100_j5_target := REAL_TO_INT(-3337.0 + 0.0 * TIME_TO_REAL(agent_motion_timer3.ET) / 1.0);
    rb100_j6_target := REAL_TO_INT(4834.0 + 0.0 * TIME_TO_REAL(agent_motion_timer3.ET) / 1.0);
    IF agent_motion_dwell3.Q THEN agent_motion_state := 4; END_IF;
  ELSE
    rb100_j1_target := 879;
    rb100_j2_target := -6719;
    rb100_j3_target := 5180;
    rb100_j4_target := 3892;
    rb100_j5_target := -3337;
    rb100_j6_target := 4834;
    agent_motion_done := 1;
  END_CASE;
END_IF;
